SELECT
  w.work_no,
  w.plan_start_date,
  w.plan_end_date,
  w.plan_qty,
  w.status
FROM work_orders w


    w.work_no = #{criteria.workNo}


    AND w.status = #{criteria.status}


    AND w.plan_start_date >= #{criteria.fromDate}


    AND w.plan_start_date <= #{criteria.toDate}


ORDER BY w.id DESC

  LIMIT #{criteria.limit} OFFSET #{criteria.offset}

